// GIVEN. Do not edit this file.
using Microsoft.Data.Sqlite;

namespace DatabasesLab;

/// <summary>
/// Runs every part of the lab against a scratch database file and prints what happened.
/// A part that is not finished yet prints "Not finished yet." instead of crashing.
/// </summary>
public static class LabCheck
{
    private const int LabelWidth = 32;
    private static readonly string CheckFile = Path.Combine(Path.GetTempPath(), "csci1260-databases-check.db");

    public static void Run()
    {
        Console.WriteLine("=== CSCI 1260 DATABASES LAB ===");
        RunPart("Part A: save it", PartA);
        RunPart("Part B: read it back", PartB);
        RunPart("Part C: show it", PartC);
        FreshFile();
    }

    // ---------------------------------------------------------------
    // The three parts
    // ---------------------------------------------------------------

    private static void PartA()
    {
        LostAndFoundDb db = new LostAndFoundDb(CheckFile);

        db.CreateTable();
        Line("Create the table:", TableShape());
        db.CreateTable();
        Line("Create it again:", "ok");

        Line("Add water bottle, Library:", db.Add("water bottle", "Library").ToString());
        Line("Add Mom's keys, Culp Center:", db.Add("Mom's keys", "Culp Center").ToString());
        Line("Add a blank description:", Refused(() => db.Add("   ", "Library")));
        Line("Rows in the file:", CountRows().ToString());

        Line("Claim #2:", db.Claim(2).ToString());
        Line("Claim #2 again:", db.Claim(2).ToString());
        Line("Add calculator, Lamb Hall:", db.Add("calculator", "Lamb Hall").ToString());
        Line("Rows in the file:", CountRows().ToString());
    }

    private static void PartB()
    {
        Seed(("water bottle", "Library"), ("Mom's keys", "Culp Center"),
             ("umbrella", "Library"), ("calculator", "Lamb Hall"));
        LostAndFoundDb db = new LostAndFoundDb(CheckFile);

        Rows("All items:", Texts(db.All()));
        Line("Count:", db.Count().ToString());
        Rows("Search \"library\":", Texts(db.Search("library")));
        Rows("Search \"KEYS\":", Texts(db.Search("KEYS")));
        Rows("Search \"' OR 1=1 --\":", Texts(db.Search("' OR 1=1 --")));
        Line("Search \"\":", db.Search("").Count + " items");
    }

    private static void PartC()
    {
        Seed(("water bottle", "Library"), ("Mom's keys", "Culp Center"), ("umbrella", "Library"));

        WindowDriver desk = WindowDriver.Open(CheckFile);
        Rows("Window opens with:", desk.ListedItems());
        Line("Count text:", desk.Text("CountText"));

        desk.Type("DescriptionBox", "calculator");
        desk.Type("LocationBox", "Lamb Hall");
        desk.Click("AddButton");
        Line("Add calculator, Lamb Hall:", desk.Text("StatusText"));
        Line("Boxes after Add:", Shown(desk.BoxText("DescriptionBox")) + " " + Shown(desk.BoxText("LocationBox")));
        Line("Rows in the list after Add:", desk.ListedItems().Count.ToString());

        desk.Type("DescriptionBox", "scarf");
        desk.Type("LocationBox", "  ");
        desk.Click("AddButton");
        Line("Add with a blank location:", desk.Text("StatusText"));

        desk.SelectNothing();
        desk.Click("ClaimButton");
        Line("Claim with nothing selected:", desk.Text("StatusText"));
        desk.Select(2);
        desk.Click("ClaimButton");
        Line("Select #2, click Claim:", desk.Text("StatusText"));
        desk.Close();

        WindowDriver first = WindowDriver.Open(CheckFile);
        Rows("Close and reopen the window:", first.ListedItems());

        WindowDriver second = WindowDriver.Open(CheckFile);
        first.Select(1);
        first.Click("ClaimButton");
        Line("First desk claims #1:", first.Text("StatusText"));
        second.Select(1);
        second.Click("ClaimButton");
        Line("Second desk claims #1 too:", second.Text("StatusText"));
        Line("Second desk count text:", second.Text("CountText"));

        second.Type("SearchBox", "lamb");
        Rows("Search box \"lamb\":", second.ListedItems());
        second.Type("SearchBox", "");
        Rows("Search box cleared:", second.ListedItems());

        first.Close();
        second.Close();
    }

    // ---------------------------------------------------------------
    // Running and printing
    // ---------------------------------------------------------------

    private static void RunPart(string title, Action part)
    {
        Console.WriteLine();
        Console.WriteLine(title);
        try
        {
            FreshFile();
            part();
        }
        catch (NotImplementedException)
        {
            Console.WriteLine("  Not finished yet.");
        }
        catch (NotFinishedException)
        {
            Console.WriteLine("  Not finished yet.");
        }
        catch (Exception ex)
        {
            Console.WriteLine("  Crashed: " + ex.GetType().Name + ": " + ex.Message);
        }
    }

    private static void Line(string label, string value)
    {
        Console.WriteLine("  " + label.PadRight(LabelWidth) + value);
    }

    private static void Rows(string label, List<string> rows)
    {
        if (rows.Count == 0)
        {
            Line(label, "(none)");
        }
        else
        {
            Console.WriteLine("  " + label);
            foreach (string row in rows)
            {
                Console.WriteLine("    " + row);
            }
        }
    }

    private static List<string> Texts(List<FoundItem> items)
    {
        List<string> texts = new List<string>();
        foreach (FoundItem item in items)
        {
            texts.Add(item.ToString());
        }
        return texts;
    }

    private static string Shown(string text)
    {
        return text.Length == 0 ? "(blank)" : text;
    }

    private static string Refused(Func<FoundItem> attempt)
    {
        try
        {
            return attempt().ToString();
        }
        catch (ArgumentException ex)
        {
            return "refused: " + ex.Message;
        }
    }

    // ---------------------------------------------------------------
    // The check's own SQL. It never uses your LostAndFoundDb for these.
    // ---------------------------------------------------------------

    private static void FreshFile()
    {
        SqliteConnection.ClearAllPools();
        if (File.Exists(CheckFile))
        {
            File.Delete(CheckFile);
        }
    }

    private static SqliteConnection OpenCheckFile()
    {
        SqliteConnection connection = new SqliteConnection("Data Source=" + CheckFile);
        connection.Open();
        return connection;
    }

    private static string TableShape()
    {
        using SqliteConnection connection = OpenCheckFile();
        using SqliteCommand command = connection.CreateCommand();
        command.CommandText = "SELECT name FROM pragma_table_info('items') ORDER BY cid";
        List<string> columns = new List<string>();
        using SqliteDataReader reader = command.ExecuteReader();
        while (reader.Read())
        {
            columns.Add(reader.GetString(0));
        }
        return columns.Count == 0 ? "no items table" : "items (" + string.Join(", ", columns) + ")";
    }

    private static long CountRows()
    {
        using SqliteConnection connection = OpenCheckFile();
        using SqliteCommand command = connection.CreateCommand();
        command.CommandText = "SELECT COUNT(*) FROM items";
        return (long)(command.ExecuteScalar() ?? 0L);
    }

    private static void Seed(params (string Description, string Location)[] rows)
    {
        using SqliteConnection connection = OpenCheckFile();
        using SqliteCommand create = connection.CreateCommand();
        create.CommandText = """
            CREATE TABLE items (
                id          INTEGER PRIMARY KEY AUTOINCREMENT,
                description TEXT NOT NULL,
                location    TEXT NOT NULL
            )
            """;
        create.ExecuteNonQuery();

        foreach ((string description, string location) in rows)
        {
            using SqliteCommand insert = connection.CreateCommand();
            insert.CommandText = "INSERT INTO items (description, location) VALUES (@d, @l)";
            insert.Parameters.AddWithValue("@d", description);
            insert.Parameters.AddWithValue("@l", location);
            insert.ExecuteNonQuery();
        }
    }
}
